begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('31111111-1111-4111-8111-111111111111'),('32222222-2222-4222-8222-222222222222');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"32222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
insert into public.anniversaries(id,title,event_date) values ('3bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','B','2024-02-29');
select set_config('request.jwt.claims','{"sub":"31111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
insert into public.anniversaries(id,title,event_date) values ('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','A','2024-02-29');
select is((select count(*)::int from public.anniversaries),1,'A only reads own anniversaries');
select throws_ok($$update public.anniversaries set title='bypass' where user_id=auth.uid()$$,'42501',null,'direct update blocked');
select throws_ok($$delete from public.anniversaries where user_id=auth.uid()$$,'42501',null,'direct delete blocked');
select throws_ok($$update public.anniversaries set user_id='32222222-2222-4222-8222-222222222222' where user_id=auth.uid()$$,'42501',null,'owner transfer blocked');
select throws_ok($$insert into public.anniversaries(title,event_date,user_id) values ('forged','2026-01-01','32222222-2222-4222-8222-222222222222')$$,'42501',null,'forged owner blocked');
select throws_ok($$insert into public.anniversaries(title,event_date,revision) values ('forged','2026-01-01',99)$$,'42501',null,'revision injection blocked');
select throws_ok($$insert into public.anniversaries(title,event_date,deleted_at) values ('forged','2026-01-01',now())$$,'42501',null,'deletion mark injection blocked');
select is((select count(*)::int from public.save_anniversary('3bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1,'x','2026-01-01',true,'')),0,'RPC cannot update B');
select is((select count(*)::int from public.delete_anniversary('3bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)),0,'RPC cannot delete B');
select throws_ok($$select public.save_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',null,'x','2026-01-01',true,'')$$,'22023',null,'null save revision blocked');
select throws_ok($$select public.save_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,'x','2026-01-01',true,'')$$,'22023',null,'zero revision blocked');
select throws_ok($$select public.delete_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',-1)$$,'22023',null,'negative delete revision blocked');
select is((select revision::int from public.save_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'saved','2024-02-29',true,'note')),2,'own CAS increments revision');
select is((select count(*)::int from public.save_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1,'stale','2026-01-01',false,'')),0,'stale save cannot overwrite');
select is((select title from public.anniversaries where id='3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'saved','winner preserved');
select is((select count(*)::int from public.delete_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',1)),0,'stale delete blocked');
select is((select count(*)::int from public.delete_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',2)),1,'versioned delete succeeds');
select is((select count(*)::int from public.anniversaries),0,'soft deleted record hidden');
select is((select count(*)::int from public.save_anniversary('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',3,'revive','2026-01-01',false,'')),0,'soft deleted record cannot revive');
select throws_ok($$insert into public.anniversaries(id,title,event_date) values ('3aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','retry','2026-01-01')$$,'23505',null,'deleted ID cannot be reused');
select throws_ok($$select * from private.write_limits$$,'42501',null,'client cannot read limiter');
select set_config('request.jwt.claims','{"role":"authenticated"}',true);
select throws_ok($$select public.delete_anniversary('3bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)$$,'42501',null,'missing identity blocked');
reset role;
set local role anon;
select set_config('request.jwt.claims','{}',true);
select throws_ok('select * from public.anniversaries','42501',null,'anonymous read blocked');
select throws_ok($$select public.delete_anniversary('3bbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',1)$$,'42501',null,'anonymous RPC blocked');
reset role;
select set_config('request.jwt.claims','{}',true);
-- Exhaust only synthetic fixtures; normal users cannot change these counters.
insert into private.write_limits(user_id,window_start,writes) values('31111111-1111-4111-8111-111111111111',date_trunc('minute',clock_timestamp()),120)
on conflict(user_id) do update set window_start=excluded.window_start,writes=120;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"31111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
select throws_ok($$insert into public.anniversaries(title,event_date) values ('rate limited','2026-01-01')$$,'54000',null,'successful-write rate cap enforced');
reset role;
select set_config('request.jwt.claims','{}',true);
delete from auth.users where id='31111111-1111-4111-8111-111111111111';
select is((select count(*)::int from private.write_limits where user_id='31111111-1111-4111-8111-111111111111'),0,'limiter cascades with account');
delete from auth.users where id='32222222-2222-4222-8222-222222222222';
select is((select count(*)::int from public.anniversaries where user_id in ('31111111-1111-4111-8111-111111111111','32222222-2222-4222-8222-222222222222')),0,'business data cascades with accounts');
select * from finish();
rollback;
